// The methos must be implemented accross all child class of TAMRebateJournalTrans to set the aggregated string on rebate trans based on the aggregation type.
// For example, TAMRebateJournalTransSalesInvoice it should set salesInvoiceTable.CustAccount when _aggregatedBy is 'CustAccount'
public void inititalizeRebateTransactionFromJournal(TAMRebateTrans _rebateTrans)
{
    next inititalizeRebateTransactionFromJournal(_rebateTrans);

    // Set the aggregated string on the rebate trans.
    if (rebateTable.TAMRebateDeal().METAggregatedBy == METConstants::aggregateByCustomer)
    {
        _rebateTrans.METAggregatedStr = invoiceJour.InvoiceAccount == '' ? invoicejour.OrderAccount : invoiceJour.InvoiceAccount;
    }
}

/// <summary>
/// Sets the journal value to a local buffer as the main buffer and method are internal
/// </summary>
/// <param name = "_journal">Journal table record buffer</param>
/// <param name = "_transaction">Journal transaction record buffer</param>
public void setJournalTransaction(Common _journal, Common _transaction)
{
    next setJournalTransaction(_journal, _transaction);

    invoiceJour = _journal as custInvoiceJour;
}

/// <summary>
/// Bug 351456: E2E: RE-0061 Vendor Rebate didn't pick up Purchase Price for the sales based calculations
/// </summary>
/// <param name = "_custInvoiceJour">Invoice header</param>
/// <param name = "_custInvoiceTrans">Invoice line</param>
/// <returns>Amount</returns>
protected Amount calcAmountPurchLatest(CustInvoiceJour _custInvoiceJour, CustInvoiceTrans _custInvoiceTrans)
{
    Amount ret = next calcAmountPurchLatest(_custInvoiceJour, _custInvoiceTrans);

    // in case amount is zero (no PO invoice)
    // and basis is value
    // Other criteria already in parent method TAMRebateJournalTransSalesInvoice\calcRebateTransactionRefAmount
    if (!ret
    && rebateTable.RebateBasis == TAMRebateBasis::Value)
    {
        // Get the price from the latest inventory base price for that item, site and vendor combination.
        ret = this.metCalcAmountBasePricePurchasePrice(_custInvoiceJour, _custInvoiceTrans);
    }

    return ret;
}

/// <summary>
/// Bug 351456: E2E: RE-0061 Vendor Rebate didn't pick up Purchase Price for the sales based calculations
/// </summary>
/// <param name = "_custInvoiceJour">Invoice header</param>
/// <param name = "_custInvoiceTrans">Invoice line</param>
/// <returns>Item base price amount</returns>
protected Amount metCalcAmountBasePricePurchasePrice(CustInvoiceJour _custInvoiceJour, CustInvoiceTrans _custInvoiceTrans)
{
    GUPItemBasePrice    itemBasePrice;
    InventDim inventDim, inventDimInvoice;

    inventDimInvoice = _custInvoiceTrans.inventDim();

    select firstonly itemBasePrice
        order by FromDate desc
        where itemBasePrice.ItemId == _custInvoiceTrans.ItemId
           && itemBasePrice.AccountRelation == rebateTable.METVendAccount
           && itemBasePrice.PriceType == GUPBasePriceType::BasePricePurchase
         exists join inventDim
               where inventDim.inventDimId  == itemBasePrice.inventDimId
                  && inventDim.InventSiteId == inventDimInvoice.InventSiteId;

    if (!itemBasePrice)
    {
        throw error(strFmt('@MET:CalcAmountBasePricePurchasePriceError', _custInvoiceTrans.ItemId, inventDimInvoice.InventSiteId, rebateTable.METVendAccount));
    }

    return CurrencyExchangeHelper::curAmount(
        itemBasePrice.Price * _custInvoiceTrans.InventQty,
        _custInvoiceTrans.CurrencyCode,
        _custInvoiceTrans.InvoiceDate);
}
